type QuestionStat = {questionId:string;index:number;stem:string;type:string;voided:boolean;eligible:number;responses:number;correct:number;partiallyCorrect:number;incorrect:number;unanswered:number;correctPercent:number;parts:{id:string;label:string;position?:number;correct:number;eligible:number;percent:number}[]};
type Results = { individual: Standing[]; team: Standing[]; participants: Standing[]; questionStats: QuestionStat[]; attemptStatuses: {participant_id:string;state:string}[] };
